Publication lifecycle
How a method goes from arXiv / bioRxiv preprint to a peer-reviewed publication. Each pairing is recorded explicitly rather than inferred from titles or dates, taken from bioRxiv’s own record of where a preprint was published, Crossref’s preprint relations, or hand-checked author overlap. Peer-reviewed, ML-conference and thesis publications all count as “post-preprint”. The Status column tells you whether each row is paired (lifecycle complete), preprint-only (still in flight), or peer-reviewed-only (published without a preprint we have on file).

lifecycle_rows = {
  // Pairing comes from the explicit publication_version table, built offline
  // by build_versions.py from bioRxiv's `published` field, Crossref
  // is-preprint-of relations, exact normalised-title matches and
  // human-reviewed fuzzy candidates.
  //
  // This used to be guessed here: publications were bucketed by (first
  // algorithm name, version) and each preprint greedily claimed the earliest
  // later peer-reviewed paper in its bucket. That read only
  // `models.split(",")[0]`, so a paper linked to several algorithms was
  // bucketed by whichever came first; a paper with no algorithm link could
  // never pair at all; and date-order greed could hand one journal paper to
  // the wrong preprint. The table also refuses that last case outright, via a
  // UNIQUE index on published_id.
  const POST_PREPRINT = new Set(["peer-reviewed", "ML conference", "thesis"])

  // The method label the y-axis and the Method column display. Version is kept
  // separate because Casanovo has versioned releases (v1 / v2 / v5) that each
  // went through their own preprint-to-journal cycle.
  const label_of = p =&gt; ({
    method: (p.models ?? "").split(",")[0]?.trim()
            || (p.title ?? "").slice(0, 40)
            || `#${p.id}`,
    version: p.version || null
  })
  const url_of = p =&gt; p.url || (p.doi ? `https://doi.org/${p.doi}` : null)

  // Only pair when BOTH halves survive the global filters, so the chart never
  // shows a pairing the reader has filtered half of away.
  const visible = new Map(pubs_filtered.map(p =&gt; [p.id, p]))
  const rows = []
  const claimed = new Set()

  for (const pp of pubs_filtered) {
    if (pp.type !== "preprint") continue
    const target_id = published_of.get(pp.id)
    const target = target_id != null ? visible.get(target_id) : null
    const { method, version } = label_of(pp)
    if (target) {
      claimed.add(target.id)
      const gap_months = ((target.date ?? 0) - (pp.date ?? 0)) / 86400000 / 30.44
      rows.push({
        method, version, status: "paired",
        preprint_id: pp.id, peer_id: target.id,
        preprint_date: pp.date, preprint_title: pp.title, preprint_url: url_of(pp),
        peer_date: target.date, peer_title: target.title, peer_url: url_of(target),
        gap_months: Math.round(gap_months * 10) / 10
      })
    } else {
      rows.push({
        method, version, status: "preprint-only",
        preprint_id: pp.id, peer_id: null,
        preprint_date: pp.date, preprint_title: pp.title, preprint_url: url_of(pp),
        peer_date: null, peer_title: null, peer_url: null, gap_months: null
      })
    }
  }

  for (const p of pubs_filtered) {
    if (!POST_PREPRINT.has(p.type) || claimed.has(p.id)) continue
    const { method, version } = label_of(p)
    rows.push({
      method, version, status: "peer-reviewed-only",
      preprint_id: null, peer_id: p.id,
      preprint_date: null, preprint_title: null, preprint_url: null,
      peer_date: p.date, peer_title: p.title, peer_url: url_of(p), gap_months: null
    })
  }

  // Order: paired first (shortest gap first), then preprint-only by preprint
  // date (oldest first = the longest-outstanding follow-ups), then
  // peer-reviewed-only by year.
  const status_rank = { "paired": 0, "preprint-only": 1, "peer-reviewed-only": 2 }
  return rows.sort((a, b) =&gt; {
    const s = status_rank[a.status] - status_rank[b.status]
    if (s !== 0) return s
    if (a.status === "paired") return a.gap_months - b.gap_months
    return (a.preprint_date ?? a.peer_date ?? 0) - (b.preprint_date ?? b.peer_date ?? 0)
  })
}







