  const table = Inputs.table(author_search, {
    columns: ["name", "papers", "methods", "kinds", "affiliations", "countries"],
    header: {
      name: "Author", papers: "Papers", methods: "Method(s)",
      kinds: "Kind(s)", affiliations: "Affiliation(s)", countries: "Country / countries"
    },
    format: {
      papers:       n =&gt; n == null ? "" : String(n),
      name:         n =&gt; page_link("authors", n, n),
      // affiliations is a "Institution / Department" list joined by "; ".
      // Only the institution half has a page, so link that and keep the
      // department as plain text.
      affiliations: s =&gt; {
        if (!s) return ""
        const parts = String(s).split(";").map(x =&gt; x.trim()).filter(Boolean)
        const out = []
        parts.slice(0, 2).forEach((part, idx) =&gt; {
          if (idx) out.push("; ")
          const cut = part.indexOf(" / ")
          const inst = cut === -1 ? part : part.slice(0, cut)
          out.push(page_link("institutions", inst, inst))
          if (cut !== -1) out.push(part.slice(cut))
        })
        if (parts.length &gt; 2) out.push(` +${parts.length - 2}`)
        return htl.html`${out}`
      },
      methods:      s =&gt; page_links("algorithms", s, { max: 4 })
    },
    sort: "papers",
    reverse: true,
    rows: 25,
    width: { name: 180, papers: 70, methods: 220, kinds: 130, affiliations: 320, countries: 120 }
  })
  return html`&lt;div class="chart-wrap"&gt;
    &lt;button class="fs-btn" onclick="
      const el = this.parentElement;
      if (document.fullscreenElement) document.exitFullscreen();
      else el.requestFullscreen();
    "&gt;⛶ Fullscreen&lt;/button&gt;
    &lt;div class="chart-scroll"&gt;${table}&lt;/div&gt;
  &lt;/div&gt;`
}
